/* From Uiverse.io by WrongCodeU - Tags: subscription, blue, card, box-shadow */
.__UIV_SCOPE__ .card {
  width: 12em;
  height: 15em;
  background: lightblue;
  border-radius: 1em;
  border-color: black;
  border-style: solid;
  border-width: 0.4em;
  box-shadow: 0.3em 0.3em black;
}

.__UIV_SCOPE__ .svg-icon {
  margin-top: 0.3em;
  margin-left: 0.5em;
  width: 2em;
  height: 2.5em;
}

.__UIV_SCOPE__ .svg-icon path,
.__UIV_SCOPE__ .svg-icon polygon,
.__UIV_SCOPE__ .svg-icon rect {
  fill: rgb(0, 110, 255);
}

.__UIV_SCOPE__ .svg-icon circle {
  stroke: #000;
  stroke-width: 1;
}

.__UIV_SCOPE__ .Name-9999 {
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: 900;
  font-size: 2em;
  margin-left: 0.5em;
}

.__UIV_SCOPE__ .Price-9999 {
  margin-bottom: 0.3em;
  margin-top: -0.3em;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: 900;
  font-size: 3em;
  margin-left: 0.3em;
}

.__UIV_SCOPE__ .Description-9999 {
  font-size: 1.1em;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: 900;
  position: relative;
  margin-left: 4em;
  margin-top: -2.4em;
}

.__UIV_SCOPE__ .YouGet-9999 {
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: 900;
  position: relative;
  margin-left: 4em;
  margin-top: -2.4em;
  font-size: 1.1em;
}

.__UIV_SCOPE__ .svg-icon2 {
  margin-top: 1em;
  margin-left: 0.5em;
  width: 2em;
  height: 2em;
}

.__UIV_SCOPE__ .svg-icon2 path,
.__UIV_SCOPE__ .svg-icon2 polygon,
.__UIV_SCOPE__ .svg-icon2 rect {
  fill: rgb(0, 110, 255);
}

.__UIV_SCOPE__ .svg-icon2 circle {
  stroke: #000;
  stroke-width: 1;
}
